// 关键点：心跳间隔 < 链路 idle timeout；重连指数退避 + 抖动；重连后必须重新鉴权和重订阅
class WSClient {
  constructor(url, getToken) {
    this.url = url;
    this.getToken = getToken; // 每次重连都拿最新 token，避免过期
    this.retry = 0;
    this.heartbeatTimer = null;
    this.pongTimer = null;
    this.connect();
  }

  connect() {
    const token = this.getToken();
    this.ws = new WebSocket(`${this.url}?token=${token}`);

    this.ws.onopen = () => {
      this.retry = 0;
      this.startHeartbeat();
      this.resubscribe(); // 服务端不会记得上次订阅，必须重新发
    };

    this.ws.onmessage = (e) => {
      const msg = JSON.parse(e.data);
      if (msg.type === 'pong') {
        clearTimeout(this.pongTimer); // 收到 pong 取消超时
        return;
      }
      this.handle(msg);
    };

    this.ws.onclose = (e) => {
      this.stopHeartbeat();
      // 1000 正常关闭不重连；1008 策略违反（如 token 过期）通常重连后能恢复
      if (e.code === 1000) return;
      const backoff = Math.min(30000, 1000 * 2 ** this.retry++);
      const jitter = backoff * (0.8 + Math.random() * 0.4);
      setTimeout(() => this.connect(), jitter);
    };
  }

  startHeartbeat() {
    // 25s < 常见网关 30-60s idle timeout
    this.heartbeatTimer = setInterval(() => {
      if (this.ws.readyState !== WebSocket.OPEN) return;
      this.ws.send(JSON.stringify({ type: 'ping' }));
      // 5s 内没收到 pong 视为链路死，主动 close 触发 onclose 重连
      this.pongTimer = setTimeout(() => this.ws.close(4000, 'pong-timeout'), 5000);
    }, 25000);
  }

  stopHeartbeat() {
    clearInterval(this.heartbeatTimer);
    clearTimeout(this.pongTimer);
  }
}
